from pathlib import Path
import re, json
root=Path('.vyron-v051')
if not root.is_dir(): raise SystemExit('VYRON source root missing')
base=json.loads((root/'package.json').read_text())
if base.get('version')!='0.9.5': raise SystemExit(f"Expected VYRON 0.9.5 base, got {base.get('version')}")

# youtube.rs
p=root/'src-tauri/src/youtube.rs'
s=p.read_text()
s=s.replace('fn youtube_error(v:&Value,fallback:&str)->String{v.pointer("/error/message").and_then(|x|x.as_str()).or_else(||v.get("error_description").and_then(|x|x.as_str())).unwrap_or(fallback).to_string()}', '''fn youtube_error(v:&Value,fallback:&str)->String{\n let message=v.pointer("/error/message").and_then(|x|x.as_str()).or_else(||v.get("error_description").and_then(|x|x.as_str())).unwrap_or(fallback);\n let reason=v.pointer("/error/errors/0/reason").and_then(|x|x.as_str()).unwrap_or("");\n if reason.is_empty(){message.to_string()}else{format!("{} [{}]",message,reason)}\n}''')
start=s.index('#[tauri::command]\npub async fn youtube_update_existing_video')
end=s.index('\n#[tauri::command]\npub async fn youtube_channel_stats', start)
new='''#[cfg(test)]\nfn youtube_truncate_utf8_bytes(input:&str,max_bytes:usize)->String{\n if input.len()<=max_bytes{return input.to_string()}\n let mut end=max_bytes.min(input.len());while end>0&&!input.is_char_boundary(end){end-=1}input[..end].to_string()\n}\n#[cfg(not(test))]\nfn youtube_truncate_utf8_bytes(input:&str,max_bytes:usize)->String{\n if input.len()<=max_bytes{return input.to_string()}\n let mut end=max_bytes.min(input.len());while end>0&&!input.is_char_boundary(end){end-=1}input[..end].to_string()\n}\nfn youtube_clean_title(input:&str)->String{input.trim().replace(['<','>']," ").chars().take(100).collect::<String>().trim().to_string()}\nfn youtube_tag_cost(tag:&str,has_previous:bool)->usize{tag.chars().count()+if tag.contains(char::is_whitespace){2}else{0}+if has_previous{1}else{0}}\nfn youtube_sanitize_tags(tags:Vec<String>)->Vec<String>{\n let mut out=Vec::<String>::new();let mut used=0usize;\n for raw in tags{let tag=raw.trim().replace(['<','>']," ").split_whitespace().collect::<Vec<_>>().join(" ");if tag.is_empty()||out.iter().any(|x|x.eq_ignore_ascii_case(&tag)){continue}let cost=youtube_tag_cost(&tag,!out.is_empty());if used+cost>500{continue}used+=cost;out.push(tag)}out\n}\nfn youtube_status_body(old_status:&Value,target_privacy:&str,publish_at:Option<&str>)->Value{\n let mut ns=json!({"privacyStatus":target_privacy});if let Some(p)=publish_at{ns["publishAt"]=json!(p);}for k in ["embeddable","license","publicStatsViewable","selfDeclaredMadeForKids","containsSyntheticMedia"]{if let Some(x)=old_status.get(k){ns[k]=x.clone();}}ns\n}\n\n#[tauri::command]\npub async fn youtube_update_existing_video(app:AppHandle,profile_id:String,video_id:String,title:String,description:String,tags:Vec<String>,publish_at:Option<String>,privacy_status:Option<String>)->Result<Value,String>{\n let (token,profile)=valid_access_token(&app,&profile_id).await?;if !profile.scopes.iter().any(|s|s=="https://www.googleapis.com/auth/youtube.force-ssl"||s=="https://www.googleapis.com/auth/youtube"){return Err("YouTube профиль подключён со старыми правами. Переподключи канал.".into())}\n let client=reqwest::Client::new();let r=client.get("https://www.googleapis.com/youtube/v3/videos").bearer_auth(&token).query(&[("part","snippet,status"),("id",video_id.as_str())]).send().await.map_err(|e|format!("YouTube video read: {e}"))?;let st=r.status();let v:Value=r.json().await.map_err(|e|e.to_string())?;if !st.is_success(){return Err(youtube_error(&v,"Не удалось перечитать видео"))}let item=v.get("items").and_then(|x|x.as_array()).and_then(|a|a.first()).ok_or_else(||"Видео не найдено".to_string())?;let sn=item.get("snippet").cloned().unwrap_or_else(||json!({}));let old_status=item.get("status").cloned().unwrap_or_else(||json!({}));if profile.channel_id.as_deref()!=sn.get("channelId").and_then(|x|x.as_str()){return Err(format!("BLOCK {}: video.channelId не совпадает с oauthProfile.channelId",video_id))}\n let wanted_title=youtube_clean_title(&title);if wanted_title.is_empty(){return Err("YouTube title не может быть пустым".into())}let wanted_desc=youtube_truncate_utf8_bytes(&description,5000);let wanted_tags=youtube_sanitize_tags(tags);let category=sn.get("categoryId").and_then(|x|x.as_str()).unwrap_or("10");\n // Phase 1: metadata only. A schedule error must never roll back title/description/tags.\n let snippet_body=json!({"id":video_id,"snippet":{"title":wanted_title,"description":wanted_desc,"tags":wanted_tags,"categoryId":category}});\n let u=client.put("https://www.googleapis.com/youtube/v3/videos").bearer_auth(&token).query(&[("part","snippet")]).json(&snippet_body).send().await.map_err(|e|format!("YouTube metadata update: {e}"))?;let ust=u.status();let uv:Value=u.json().await.unwrap_or_else(|_|json!({}));if !ust.is_success(){return Err(format!("METADATA: {}",youtube_error(&uv,"YouTube не принял title/description/tags")))}\n let check=client.get("https://www.googleapis.com/youtube/v3/videos").bearer_auth(&token).query(&[("part","snippet,status"),("id",video_id.as_str())]).send().await.map_err(|e|format!("YouTube metadata verify: {e}"))?;let cst=check.status();let cv:Value=check.json().await.unwrap_or_else(|_|json!({}));if !cst.is_success(){return Err(youtube_error(&cv,"YouTube metadata verify не выполнен"))}let got=cv.get("items").and_then(|x|x.as_array()).and_then(|a|a.first()).ok_or_else(||format!("Verify {}: видео не найдено",video_id))?;let gsn=got.get("snippet").cloned().unwrap_or_else(||json!({}));let current_status=got.get("status").cloned().unwrap_or_else(||old_status.clone());let actual_tags=gsn.get("tags").and_then(|x|x.as_array()).cloned().unwrap_or_default().into_iter().filter_map(|x|x.as_str().map(str::to_string)).collect::<Vec<_>>();let wanted_tags=snippet_body.pointer("/snippet/tags").and_then(|x|x.as_array()).cloned().unwrap_or_default().into_iter().filter_map(|x|x.as_str().map(str::to_string)).collect::<Vec<_>>();let mut md_diff=Vec::<String>::new();if gsn.get("title").and_then(|x|x.as_str())!=snippet_body.pointer("/snippet/title").and_then(|x|x.as_str()){md_diff.push("title".into())}if gsn.get("description").and_then(|x|x.as_str())!=snippet_body.pointer("/snippet/description").and_then(|x|x.as_str()){md_diff.push("description".into())}if actual_tags!=wanted_tags{md_diff.push("tags".into())}if !md_diff.is_empty(){return Err(format!("METADATA VERIFY {}: {}",video_id,md_diff.join(", ")))}\n let old_privacy=current_status.get("privacyStatus").and_then(|x|x.as_str()).unwrap_or("private");let target_privacy=privacy_status.as_deref().filter(|x|matches!(*x,"private"|"public"|"unlisted")).unwrap_or(old_privacy).to_string();let publish=publish_at.as_deref().map(str::trim).filter(|x|!x.is_empty());let schedule_requested=publish.is_some()||target_privacy!=old_privacy;\n if !schedule_requested{return Ok(json!({"id":video_id,"verified":true,"metadataVerified":true,"scheduleRequested":false,"scheduleVerified":true,"scheduleError":Value::Null,"appliedTags":wanted_tags.len()}))}\n // Phase 2: privacy/schedule. Failure here is returned as a partial success with concrete reason.\n if publish.is_some()&&target_privacy!="private"{return Ok(json!({"id":video_id,"verified":false,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":false,"scheduleError":"Scheduled publishAt требует privacyStatus=private","appliedTags":wanted_tags.len()}))}\n if let Some(p)=publish{match chrono::DateTime::parse_from_rfc3339(p){Ok(dt)=>{if dt.with_timezone(&Utc)<=Utc::now(){return Ok(json!({"id":video_id,"verified":false,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":false,"scheduleError":"Дата публикации уже в прошлом. Метаданные сохранены, расписание не изменено.","appliedTags":wanted_tags.len()}))}},Err(_)=>return Ok(json!({"id":video_id,"verified":false,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":false,"scheduleError":"Некорректный publishAt: ожидается RFC3339","appliedTags":wanted_tags.len()}))}}}\n let status_body=json!({"id":video_id,"status":youtube_status_body(&current_status,&target_privacy,publish)});let su=client.put("https://www.googleapis.com/youtube/v3/videos").bearer_auth(&token).query(&[("part","status")]).json(&status_body).send().await.map_err(|e|format!("YouTube schedule update: {e}"))?;let sst=su.status();let sv:Value=su.json().await.unwrap_or_else(|_|json!({}));if !sst.is_success(){return Ok(json!({"id":video_id,"verified":false,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":false,"scheduleError":youtube_error(&sv,"YouTube не принял расписание/privacy"),"appliedTags":wanted_tags.len()}))}\n let verify=client.get("https://www.googleapis.com/youtube/v3/videos").bearer_auth(&token).query(&[("part","status"),("id",video_id.as_str())]).send().await.map_err(|e|format!("YouTube schedule verify: {e}"))?;let vst=verify.status();let vv:Value=verify.json().await.unwrap_or_else(|_|json!({}));if !vst.is_success(){return Ok(json!({"id":video_id,"verified":false,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":false,"scheduleError":youtube_error(&vv,"YouTube schedule verify не выполнен"),"appliedTags":wanted_tags.len()}))}let gst=vv.pointer("/items/0/status").cloned().unwrap_or_else(||json!({}));let mut sd=Vec::<String>::new();if let Some(w)=publish{if !same_publish_time(Some(w),gst.get("publishAt").and_then(|x|x.as_str())){sd.push("publishAt")}}if gst.get("privacyStatus").and_then(|x|x.as_str())!=Some(target_privacy.as_str()){sd.push("privacyStatus")}if !sd.is_empty(){return Ok(json!({"id":video_id,"verified":false,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":false,"scheduleError":format!("YouTube не подтвердил расписание {}: {}",video_id,sd.join(", ")),"appliedTags":wanted_tags.len()}))}\n Ok(json!({"id":video_id,"verified":true,"metadataVerified":true,"scheduleRequested":true,"scheduleVerified":true,"scheduleError":Value::Null,"appliedTags":wanted_tags.len()}))\n}\n\n#[cfg(test)]\nmod youtube_write_tests{use super::*;#[test]fn utf8_description_respects_5000_bytes(){let s="я".repeat(3000);let out=youtube_truncate_utf8_bytes(&s,5000);assert!(out.len()<=5000);assert!(out.is_char_boundary(out.len()));}#[test]fn tags_respect_youtube_500_budget(){let tags=(0..100).map(|i|format!("long tag number {} abcdefghijklmnop",i)).collect::<Vec<_>>();let out=youtube_sanitize_tags(tags);let mut used=0;for (i,t) in out.iter().enumerate(){used+=youtube_tag_cost(t,i>0);}assert!(used<=500);assert!(!out.is_empty());}#[test]fn tags_dedupe_and_strip_angle_brackets(){let out=youtube_sanitize_tags(vec![" alpha ".into(),"ALPHA".into(),"<beta tag>".into()]);assert_eq!(out.len(),2);assert!(!out[1].contains('<'));assert!(!out[1].contains('>'));}}\n'''
s=s[:start]+new+s[end:]
p.write_text(s)

# api.ts
p=root/'src/api.ts'; s=p.read_text(); s=s.replace("invoke<{id:string;verified:boolean}>('youtube_update_existing_video'", "invoke<{id:string;verified:boolean;metadataVerified:boolean;scheduleRequested:boolean;scheduleVerified:boolean;scheduleError?:string|null;appliedTags?:number}>('youtube_update_existing_video'"); p.write_text(s)

# MetadataPage.tsx
p=root/'src/MetadataPage.tsx'; s=p.read_text()
s=s.replace("type Match={row:ImportedMetadata;job?:VideoJob;video?:YoutubeExistingVideo;index:number};", "type Match={row:ImportedMetadata;job?:VideoJob;video?:YoutubeExistingVideo;index:number};\ntype ApplyIssue={videoId:string;title:string;phase:'metadata'|'schedule';error:string};\ntype ApplyReport={metadataOk:number;total:number;scheduleOk:number;scheduleTotal:number;failed:number;issues:ApplyIssue[]};")
old="[syncStatus,setSyncStatus]=useState('');const file=useRef<HTMLInputElement>(null);"
newstate="[syncStatus,setSyncStatus]=useState(''),[applyProgress,setApplyProgress]=useState(''),[applyReport,setApplyReport]=useState<ApplyReport|null>(null);const file=useRef<HTMLInputElement>(null);"
if old not in s: raise SystemExit('metadata state marker missing')
s=s.replace(old,newstate)
s=s.replace("useEffect(()=>{setCadence(channel?.cadenceDays||2);setYt([]);setRows([]);setDocxStrict(false)},[channelId]);", "useEffect(()=>{setCadence(channel?.cadenceDays||2);setYt([]);setRows([]);setDocxStrict(false);setApplyProgress('');setApplyReport(null)},[channelId]);")
old_apply=re.search(r" async function applyYoutube\(\)\{.*?\n async function apply\(\)",s,re.S)
if not old_apply: raise SystemExit('applyYoutube marker missing')
new_apply=''' async function applyYoutube(){if(!profileId||!selectedYt.length)return;if(docxStrict&&rows.length!==selectedYt.length){toast('DOCX не применён: количество выбранных видео изменилось после импорта');return}setBusy(true);setApplyReport(null);let metadataOk=0,scheduleOk=0,scheduleTotal=0,failed=0;const issues:ApplyIssue[]=[];try{const scheduled=buildExistingScheduleFromLocal(selectedYt,start,cadence,rows);const scheduleById=new Map(scheduled.map(v=>[v.id,v.publishAt]));await api.youtubeBackupExisting(profileId,selectedYt);let done=0;for(const m of matches){const v=m.video,r=m.row;if(!v)continue;done++;setApplyProgress(`${done}/${matched}`);try{const publishAt=v.privacyStatus==='private'?(r.publishAt||scheduleById.get(v.id)||v.publishAt):v.publishAt;const result=await api.youtubeUpdateExisting(profileId,v.id,r.title||v.title,r.description||v.description,r.tags?.length?r.tags:v.tags,publishAt,v.privacyStatus);if(result.metadataVerified)metadataOk++;else{failed++;issues.push({videoId:v.id,title:v.title,phase:'metadata',error:'YouTube не подтвердил title/description/tags'});continue}if(result.scheduleRequested){scheduleTotal++;if(result.scheduleVerified)scheduleOk++;else issues.push({videoId:v.id,title:v.title,phase:'schedule',error:result.scheduleError||'YouTube не подтвердил расписание'})}}catch(e){failed++;issues.push({videoId:v.id,title:v.title,phase:'metadata',error:String(e)})}}const report={metadataOk,total:matched,scheduleOk,scheduleTotal,failed,issues};setApplyReport(report);toast(`Метаданные ${metadataOk}/${matched}${scheduleTotal?` • расписание ${scheduleOk}/${scheduleTotal}`:''}${failed?` • полностью ошибок ${failed}`:''}${issues.length?` • детали ниже`:''}`);if(metadataOk)await loadYoutube()}catch(e){const issue={videoId:'BATCH',title:'Пакетная операция',phase:'metadata' as const,error:String(e)};setApplyReport({metadataOk,total:matched,scheduleOk,scheduleTotal,failed:failed+1,issues:[...issues,issue]});toast(`YouTube apply: ${String(e)}`)}finally{setApplyProgress('');setBusy(false)}}\n async function apply()'''
s=s[:old_apply.start()]+new_apply+s[old_apply.end():]
s=s.replace("{busy?'Применяю…':`Применить ${matched}`}", "{busy?`Применяю ${applyProgress||'…'}`:`Применить ${matched}`}" )
marker="  <input ref={file} hidden type=\"file\""
report_jsx='''  {applyReport&&<section className="panel"><div className="panelHead"><div><small>YOUTUBE WRITE REPORT</small><h3>{applyReport.failed===0&&applyReport.issues.length===0?'✓ Запись подтверждена':'Результат применения'}</h3></div><button onClick={()=>setApplyReport(null)}>Закрыть</button></div><div className="syncAudit"><span>Метаданные <b>{applyReport.metadataOk}/{applyReport.total}</b></span>{applyReport.scheduleTotal>0&&<span>Расписание <b>{applyReport.scheduleOk}/{applyReport.scheduleTotal}</b></span>}<span>Полностью не записано <b>{applyReport.failed}</b></span></div>{applyReport.issues.length>0&&<div className="metadataPreviewList">{applyReport.issues.map((x,i)=><div className="metadataPreviewRow missing" key={`${x.videoId}-${i}`}><span><b>{x.phase==='schedule'?'РАСПИСАНИЕ':'МЕТАДАННЫЕ'} • {x.videoId}</b><small>{short(x.title,70)}</small></span><strong>{x.phase==='schedule'?'Метаданные сохранены, расписание не применено':'Видео не обновлено'}</strong><em>{x.error}</em></div>)}</div>}</section>}\n'''
if marker not in s: raise SystemExit('input marker missing')
s=s.replace(marker,report_jsx+marker,1)
p.write_text(s)

# ExistingVideos partial handling and visible errors; do not silently declare all failed when only schedule failed.
p=root/'src/ExistingVideos.tsx'; s=p.read_text()
old="try{const result=await api.youtubeUpdateExisting(profileId,v.id,v.title,v.description,v.tags,v.publishAt,v.privacyStatus);if(!result?.verified)throw new Error(`YouTube не подтвердил изменение ${v.id}`);ok++;verifiedIds.add(v.id);setVideos(x=>x.map(z=>z.id===v.id?{...z,applyState:'done',verified:true}:z))}catch(e){setVideos(x=>x.map(z=>z.id===v.id?{...z,applyState:'error',verified:false,error:`${v.id}: ${String(e)}`}:z))}"
newv="try{const result=await api.youtubeUpdateExisting(profileId,v.id,v.title,v.description,v.tags,v.publishAt,v.privacyStatus);if(!result?.metadataVerified)throw new Error(`YouTube не подтвердил metadata ${v.id}`);ok++;verifiedIds.add(v.id);if(result.scheduleRequested&&!result.scheduleVerified){setVideos(x=>x.map(z=>z.id===v.id?{...z,applyState:'error',verified:false,error:`${v.id}: метаданные сохранены; расписание: ${result.scheduleError||'не подтверждено'}`}:z))}else{setVideos(x=>x.map(z=>z.id===v.id?{...z,applyState:'done',verified:true}:z))}}catch(e){setVideos(x=>x.map(z=>z.id===v.id?{...z,applyState:'error',verified:false,error:`${v.id}: ${String(e)}`}:z))}"
if old not in s: raise SystemExit('existing apply marker missing')
s=s.replace(old,newv)
p.write_text(s)

# bump versions
for rel in ['package.json','package-lock.json']:
 p=root/rel; d=json.loads(p.read_text()); d['version']='0.9.6';
 if rel=='package-lock.json' and '' in d.get('packages',{}): d['packages']['']['version']='0.9.6'
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
p=root/'src-tauri/tauri.conf.json'; d=json.loads(p.read_text()); d['version']='0.9.6'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
p=root/'src-tauri/Cargo.toml'; s=p.read_text(); s=s.replace('version = "0.9.5"','version = "0.9.6"',1); p.write_text(s)
p=root/'src-tauri/Cargo.lock'; s=p.read_text(); s=s.replace('name = "channelflow"\nversion = "0.9.5"','name = "channelflow"\nversion = "0.9.6"',1); p.write_text(s)
for rel in ['src/App.tsx','src/SettingsOS.tsx']:
 p=root/rel
 if p.exists(): p.write_text(p.read_text().replace('0.9.5','0.9.6'))
assert json.loads((root/'package.json').read_text())['version']=='0.9.6'
assert 'catch{err++}' not in (root/'src/MetadataPage.tsx').read_text()
assert 'metadataVerified' in (root/'src/MetadataPage.tsx').read_text()
assert 'Phase 1: metadata only' in (root/'src-tauri/src/youtube.rs').read_text()
print('VYRON 0.9.6 metadata write fix applied')
